exercises.solution:
def recevoir(stock, article, quantite):
    if quantite <= 0:
        return None
    copie = stock.copy()
    copie[article] = copie.get(article, 0) + quantite
    return copie

def total_prevu(stock, quantite):
    total = quantite
    for code in stock:
        total = total + stock[code]
    return total

def recevoir_lot(stock, livraisons):
    copie = stock.copy()
    for article, quantite in livraisons:
        copie[article] = copie.get(article, 0) + quantite
    return copie

def retirer(stock, article, quantite):
    if article not in stock or quantite <= 0:
        return None
    if stock[article] < quantite:
        return None
    copie = stock.copy()
    copie[article] = copie[article] - quantite
    return copie

def manque(stock, article, demande):
    disponible = stock.get(article, 0)
    if demande > disponible:
        return demande - disponible
    return 0

