def appliquer_ajouts(stock, operations):
    copie = stock.copy()
    for type_op, article, quantite in operations:
        if type_op == "ajout" and quantite > 0:
            copie[article] = copie.get(article, 0) + quantite
    return copie

def compter_invalides(operations):
    nombre = 0
    for type_op, article, quantite in operations:
        if type_op not in ["ajout", "retrait"] or quantite <= 0:
